import{_ as a,o as i,c as p,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const x=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Statistical-Distribution-Functions.md","filePath":"manual-zh/Statistical-Distribution-Functions.md","lastUpdated":1785684581000}'),d={name:"manual-zh/Statistical-Distribution-Functions.md"};function e(r,t,o,n,c,l){return i(),p("div",null,[...t[0]||(t[0]=[s('<h4 id="_7-7-10-统计分布函数" tabindex="-1">7.7.10 统计分布函数 <a class="header-anchor" href="#_7-7-10-统计分布函数" aria-label="Permalink to &quot;7.7.10 统计分布函数&quot;">​</a></h4><p>PSPP 可以计算若干标准统计分布的函数。这些函数根据函数类型与分布进行系统化命名。下表总体上描述了统计分布函数：</p><p>PDF.dist (x[, param…])</p><p>dist 的概率密度函数。x 的定义域取决于 dist。对于连续分布，结果为 x 处概率函数的密度，值域为非负实数；对于离散分布，结果为 x 的概率。</p><p>CDF.dist (x[, param…])</p><p>dist 的累积分布函数，即从该分布中抽取的随机变量小于 x 的概率。x 的定义域取决于 dist。结果为一个概率。</p><p>SIG.dist (x[, param…)</p><p>dist 的尾概率函数，即从该分布中抽取的随机变量大于 x 的概率。x 的定义域取决于 dist。结果为一个概率。仅有少数分布包含 <code>SIG</code> 函数。</p><p>IDF.dist (p[, param…])</p><p>dist 的逆分布函数，即使得 CDF 得出 p 的 x 值。p 的值为一个概率。值域取决于 dist，并与对应 CDF 的定义域相同。</p><p>RV.dist ([param…])</p><p>dist 的随机变量函数。值域取决于分布。</p><p>NPDF.dist (x[, param…])</p><p>非中心概率密度函数。结果为给定非中心分布在 x 处的密度。x 的定义域取决于 dist。值域为非负实数。仅有少数分布包含 <code>NPDF</code> 函数。</p><p>NCDF.dist (x[, param…])</p><p>dist 的非中心累积分布函数，即从给定非中心分布中抽取的随机变量小于 x 的概率。x 的定义域取决于 dist。结果为一个概率。仅有少数分布包含 NCDF 函数。</p><p>各具体分布将在下面分别描述。</p><table tabindex="0"><thead><tr><th>• 连续分布</th><th></th><th></th></tr></thead><tbody><tr><td>• 离散分布</td><td></td><td></td></tr></tbody></table>',18)])])}const m=a(d,[["render",e]]);export{x as __pageData,m as default};
